def D(n):
    """Calculates D(n) = n^3 + 4n^2 + 6n + 4"""
    return n**3 + 4*n**2 + 6*n + 4

def is_2_5_smooth(n):
    """Checks if n is of the form 2^a * 5^b"""
    if n <= 0:
        return False
    while n > 0 and n % 2 == 0:
        n //= 2
    while n > 0 and n % 5 == 0:
        n //= 5
    return n == 1

# List of candidates to test, including those specified in the prompt (n>=12)
# We will test a range and filter based on W3 constraints if necessary,
# but primarily focus on the requested list: 12, 14, 15, 17, 18, ...
# Let's test up to n=20 for good measure.
test_values = range(12, 21)

results = {}
for n in test_values:
    # Applying W3 constraints (n not 1 mod 3, n not 5 mod 7)
    if n % 3 == 1 or n % 7 == 5:
        results[n] = "ELIMINATED by W3 constraints"
        continue

    d_n = D(n)
    smooth = is_2_5_smooth(d_n)

    if smooth:
        results[n] = "2/5-SMOOTH (Potential Solution)"
    else:
        results[n] = "NOT 2/5-SMOOTH (Eliminated)"

print(results)

